def value = $('message', null);
if (!(value instanceof String)) { return; }
String text = (String) value;
def m = /((?<![0-9])(?:[0-9][ .-]?){12,18}[0-9](?![0-9]))/.matcher(text);
String out = ''; int last = 0; boolean any = false;
while (m.find()) {
  String cand = m.group(1); int gs = m.start(1); int ge = m.end(1);
  int sum = 0; boolean alt = false; int cnt = 0; int first = -1; boolean multi = false; for (int i = cand.length() - 1; i >= 0; i--) { char c = cand.charAt(i); if (c < (char)'0' || c > (char)'9') { continue; } int raw = c - (char)'0'; if (first < 0) { first = raw; } else if (raw != first) { multi = true; } int d = raw; cnt++; if (alt) { d *= 2; if (d > 9) { d -= 9; } } sum += d; alt = !alt; } boolean ok = (cnt > 0 && multi && sum % 10 == 0);
  out += text.substring(last, gs);
  if (ok) { out += '<CREDIT_CARD>'; any = true; } else { out += text.substring(gs, ge); }
  last = ge;
}
if (any) {
  out += text.substring(last); ctx['message'] = out;
}

def value = $('message', null);
if (!(value instanceof String)) { return; }
String text = (String) value;
def m = /((?<![A-Za-z0-9])(?:[A-Za-z]{2}[0-9]{2}[A-Za-z0-9]{11,30}|[A-Za-z]{2}[0-9]{2}(?: [A-Za-z0-9]{4})+(?: [A-Za-z0-9]{1,3})?)(?![A-Za-z0-9]))/.matcher(text);
String out = ''; int last = 0; boolean any = false;
while (m.find()) {
  String cand = m.group(1); int gs = m.start(1); int ge = m.end(1);
  String s = ''; for (int i = 0; i < cand.length(); i++) { char c = cand.charAt(i); if (c == (char)' ') { continue; } if (c >= (char)'a' && c <= (char)'z') { c = (char)(c - 32); } s += c; } boolean ok; if (s.length() < 15 || s.length() > 34) { ok = false; } else { String rearr = s.substring(4) + s.substring(0, 4); long rem = 0; boolean good = true; for (int i = 0; i < rearr.length(); i++) { char c = rearr.charAt(i); int val; if (c >= (char)'0' && c <= (char)'9') { val = c - (char)'0'; rem = (rem * 10 + val) % 97; } else if (c >= (char)'A' && c <= (char)'Z') { val = c - (char)'A' + 10; rem = (rem * 100 + val) % 97; } else { good = false; break; } } ok = good && (rem == 1); }
  out += text.substring(last, gs);
  if (ok) { out += '<IBAN>'; any = true; } else { out += text.substring(gs, ge); }
  last = ge;
}
if (any) {
  out += text.substring(last); ctx['message'] = out;
}
